function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*899999+89);var e=0;for(var i=0;i<5;i++){e+=(90+R()*130)*(1+R()*3)/1000;}var up=0,down=0;for(var j=0;j<5;j++){up+=200+R()*800;down+=5+R()*40;}var avail=up/(up+down/60)*100;var sc=[];for(var k=0;k<10;k++)sc.push(40+R()*60);var mean=sc.reduce(function(a,b){return a+b;})/10;var ok=avail>99&&mean>55;return{subsystems:['energy-scheduler','reliability-auditor','benchmark-harness'],energy_kwh:+e.toFixed(3),availability_pct:+avail.toFixed(2),mean_benchmark:+mean.toFixed(1),fabric_status:ok?'all-green':'needs-attention'};}
var SEED = 100001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

